PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS erp_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS erp_accounts(code TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS erp_branches(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS erp_periods(branch_id TEXT NOT NULL REFERENCES erp_branches(id),month TEXT NOT NULL,closed_by TEXT NOT NULL,closed_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(branch_id,month));
CREATE TABLE IF NOT EXISTS erp_documents(id TEXT PRIMARY KEY,request_key TEXT UNIQUE NOT NULL,payload_hash TEXT NOT NULL,kind TEXT NOT NULL,business_date TEXT NOT NULL,branch_id TEXT NOT NULL REFERENCES erp_branches(id),actor TEXT NOT NULL,payload TEXT NOT NULL,due_minor INTEGER NOT NULL DEFAULT 0 CHECK(due_minor>=0),reverses_id TEXT UNIQUE REFERENCES erp_documents(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS erp_lines(id INTEGER PRIMARY KEY,document_id TEXT NOT NULL REFERENCES erp_documents(id),account TEXT NOT NULL REFERENCES erp_accounts(code),debit INTEGER NOT NULL CHECK(typeof(debit)='integer' AND debit>=0),credit INTEGER NOT NULL CHECK(typeof(credit)='integer' AND credit>=0),CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE INDEX IF NOT EXISTS erp_lines_document ON erp_lines(document_id);
CREATE TABLE IF NOT EXISTS erp_products(id TEXT PRIMARY KEY,name TEXT NOT NULL,price_minor INTEGER NOT NULL CHECK(price_minor>0));
CREATE TABLE IF NOT EXISTS erp_items(id TEXT PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS erp_recipes(product_id TEXT NOT NULL REFERENCES erp_products(id),item_id TEXT NOT NULL REFERENCES erp_items(id),quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(product_id,item_id));
CREATE TABLE IF NOT EXISTS erp_stock(branch_id TEXT NOT NULL REFERENCES erp_branches(id),item_id TEXT NOT NULL REFERENCES erp_items(id),quantity INTEGER NOT NULL CHECK(quantity>=0),value_minor INTEGER NOT NULL CHECK(value_minor>=0),PRIMARY KEY(branch_id,item_id));
CREATE TABLE IF NOT EXISTS erp_stock_moves(id INTEGER PRIMARY KEY,document_id TEXT NOT NULL REFERENCES erp_documents(id),item_id TEXT NOT NULL REFERENCES erp_items(id),quantity INTEGER NOT NULL,value_minor INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS erp_settlements(document_id TEXT PRIMARY KEY REFERENCES erp_documents(id),invoice_id TEXT NOT NULL REFERENCES erp_documents(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0));
CREATE TABLE IF NOT EXISTS erp_assets(id TEXT PRIMARY KEY,document_id TEXT UNIQUE NOT NULL REFERENCES erp_documents(id),name TEXT NOT NULL,cost_minor INTEGER NOT NULL CHECK(cost_minor>0),life_months INTEGER NOT NULL CHECK(life_months>0));
CREATE TABLE IF NOT EXISTS erp_depreciation(asset_id TEXT NOT NULL REFERENCES erp_assets(id),month TEXT NOT NULL,document_id TEXT UNIQUE NOT NULL REFERENCES erp_documents(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),PRIMARY KEY(asset_id,month));
CREATE TRIGGER IF NOT EXISTS erp_no_update_document BEFORE UPDATE ON erp_documents BEGIN SELECT RAISE(ABORT,'Posted documents are immutable'); END;
CREATE TRIGGER IF NOT EXISTS erp_no_delete_document BEFORE DELETE ON erp_documents BEGIN SELECT RAISE(ABORT,'Posted documents are immutable'); END;
CREATE TRIGGER IF NOT EXISTS erp_no_update_line BEFORE UPDATE ON erp_lines BEGIN SELECT RAISE(ABORT,'Posted lines are immutable'); END;
CREATE TRIGGER IF NOT EXISTS erp_no_delete_line BEFORE DELETE ON erp_lines BEGIN SELECT RAISE(ABORT,'Posted lines are immutable'); END;
